    source: '《史记·五帝本纪》（西汉·司马迁）·《山海经·大荒北经》（先秦）·《逸周书》（先秦）·《黄帝内经》（战国）·《中国神话通论》（袁珂）·《黄帝与中华民族》（何星甫）',
