    sections: [
      { type: 'paragraph', heading: '为什么景德镇是"世界瓷都"？', body: '**景德镇**是**世界公认的"瓷都"**：① 名字来源 — 宋真宗景德年间（AD 1004-1007）烧制"影青瓷"进贡，遂以年号命名"景德镇"；② 历史 — 制瓷历史 1700+ 年，从汉代就开始烧窑；③ **青花瓷** — 元代景德镇发明，世界瓷器市场的标准；④ "**工匠八方来，器成天下走**" — 鼎盛期人口 10 万，瓷业工人占 1/3；⑤ "**瓷都**"是世界上**唯一**以瓷器命名的城市。' },
      { type: 'callout', heading: '客家民系 — 江西是客家"摇篮"', body: '**江西是客家民系的重要发源地**：① 客家先民是**西晋末 + 唐末 + 北宋末**三次大移民南迁的中原人；② 江西南部（赣州）是客家先民的"中转站"——客家话"赣南话片区"是中国客家话的核心区；③ **客家围屋**（土楼）集中于赣南、闽西、粤东交界；④ **江西客家**约占中国客家人口的 1/3；⑤ 客家人从江西南迁到广东、福建、台湾、东南亚，形成了"客家文化圈"。', variant: 'info' },
      { type: 'paragraph', heading: '为什么说江西"文风鼎盛"？', body: '江西**人文鼎盛**的原因：① **书院文化** — 庐山白鹿洞书院是中国最早的书院之一（南唐）；② **科举** — 江西进士数全国第一（唐代至清代共 10500+ 进士）；③ **临川文化** — 抚州是"才子之乡"，王安石、汤显祖都出自临川；④ **江西诗派** — 黄庭坚为首的"江西诗派"影响中国 800 年；⑤ **革命摇篮** — 井冈山是中国革命的摇篮。' },
      { type: 'list', heading: '江西文化的"五大名人"', items: [
          '**陶渊明** — 田园诗鼻祖（浔阳柴桑，今九江）',
          '**王安石** — 宋代改革家、文学家（抚州临川）',
          '**文天祥** — 抗元英雄，"人生自古谁无死"',
          '**汤显祖** — 《牡丹亭》作者（抚州临川）',
          '**朱熹** — 理学集大成者（祖籍婺源，今属江西）',
      ] },
      { type: 'paragraph', heading: '为什么赣州有"江南宋城"？', body: '**赣州**被誉为"**江南宋城**"：① **宋代城墙**保存完好——这是中国现存最完整的宋代砖城墙（北宋嘉祐年间，1056-1063 年修建）；② 赣州的**古城格局**保留了宋代"街巷制"（不同于明清的胡同制）；③ **郁孤台**、**八镜台**——宋代名楼；④ **通天岩**——宋代石窟；⑤ 这些宋代遗迹让赣州有"**活着的宋代博物馆**"之称。' },
      { type: 'quote', text: '**江西**文风鼎盛，**临川**才子满天。', cite: '《中国通史》' },
    ],
