    sections: [
      { type: 'paragraph', heading: '为什么广西是少数民族之乡？', body: '**广西是中国少数民族最多的省级行政区之一**：① **壮族**是中国**人口最多的少数民族**（约 2000 万），其中 1500+ 万在广西；② 壮族占广西总人口约 31%；③ 12 个世居民族；④ **壮文+汉文**同为官方语言；⑤ **壮族铜鼓**是中国南方少数民族的代表性器物。' },
      { type: 'callout', heading: '桂林山水 + 刘三姐 — 广西的两张名片', body: '**桂林山水**和**刘三姐**是广西最有名的两张名片：① **桂林山水** — 喀斯特地貌，南宋王正功"桂林山水甲天下"评价 800 年；② **刘三姐** — 壮族民间传说人物；③ **刘三姐歌谣**已被列入**国家级非物质文化遗产**（2014 年）。', variant: 'info' },
      { type: 'paragraph', heading: '为什么壮族的铜鼓是南方民族器物之王？', body: '**铜鼓**是中国南方少数民族的"圣物"：① 起源**春秋战国**（云南楚雄万家坝出土最早的铜鼓）；② **壮族**是最主要的铜鼓民族（广西出土铜鼓 2000+ 件，居全国第一）；③ 铜鼓是祭祀、报时、战鼓、财富象征；④ **花山岩画**（左江）2016 年列入世界文化遗产。' },
      { type: 'list', heading: '广西文化的五大特色', items: [
          '**桂林山水** — 喀斯特地貌世界闻名',
          '**壮族山歌（刘三姐）** — 中国非物质文化遗产',
          '**铜鼓文化** — 中国南方少数民族器物之王',
          '**北部湾** — 中国南海最北端',
          '**桂林米粉 / 螺蛳粉** — 中国饮食文化代表',
      ] },
      { type: 'paragraph', heading: '为什么广西是东盟的桥头堡？', body: '**广西是连接中国与东盟的桥头堡**：① **北部湾经济区**是中国—东盟自贸区的前沿；② **南宁**是中国—东盟博览会永久会址（每年举办，2004 起）；③ 南宁与河内、曼谷航线密集。' },
      { type: 'quote', text: '**桂**林**山**水**甲**天**下，**阳**朔**山**水**甲**桂**林。', cite: '南宋·王正功' },
    ],
